void InputDeviceSettingsProviderAsyncWaiter::GetActionsForMouseButtonCustomization(
    std::vector<ActionChoicePtr>* out_options) {
  base::RunLoop loop;
  proxy_->GetActionsForMouseButtonCustomization(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<ActionChoicePtr>* out_options
,
             std::vector<ActionChoicePtr> options) {*out_options = std::move(options);
            loop->Quit();
          },
          &loop,
          out_options));
  loop.Run();
}

std::vector<ActionChoicePtr> InputDeviceSettingsProviderAsyncWaiter::GetActionsForMouseButtonCustomization(
    ) {
  std::vector<ActionChoicePtr> async_wait_result;
  GetActionsForMouseButtonCustomization(&async_wait_result);
  return async_wait_result;
}

